; Hi-res text map: Korean text in NanumGothic Bold, blended at 2x.
;
; A starting point for SCUMM v5/v6 (Monkey Island 1/2), SCI (KQ1) and AGS
; Korean translations. Copy it into the game folder as hires_text.map, or
; point the game's hires_text_map= setting at it.
;
; "data:" names a font shipped with ScummVM (dists/engine-data/hires_text/,
; installed as <datadir>/hires_text/). It is looked up in the extrapath first,
; then in the ScummVM data directory. See hires_text/fonts/FONTS.md for the
; licences.
[hires]
scale=2
alpha=true
face=ko

[fonts]
ko=data:hires_text/fonts/nanumgothic/NanumGothic-Bold.ttf
